// pnpm contract:generate   regenerate libs/contract/generated/* from Docs/40.API contract.md
// pnpm contract:check      fail if the generated files are out of date (CI)
//
// Outputs (deterministic: no timestamps, stable ordering):
//   operations.json           operation registry (402 ops, 450 routes)          — S1.T6
//   schemas.json              JSON Schema 2020-12 $defs for every named type      — S1.T7
//   operation-schemas.json    per-op body, response, query and path schemas
//   schema-coverage.json      what converted and what did not
//   operation-ids.ts          OperationId union type
//   errors.ts                 error code catalog (§4.3, §4.4)
//   enums.ts                  enum registry (§5)
//   role-groups.ts            role groups (§0.5)
import { createHash } from 'node:crypto';
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { join, relative } from 'node:path';
import type { Operation, OperationRegistry } from '#libs/contract/registry.types.js';
import { backendDir, docsDir, repoDir } from '../db/config.js';
import { parseContractVersion, parseErrorCatalog, parseRoleGroups } from './catalogs.js';
import { codeBlocks, lines } from './markdown.js';
import { parseAssistAllowlist, parseOperations } from './parse-operations.js';
import { CUSTOM_KEYWORDS, SchemaBuilder, type JsonSchema } from './types/json-schema.js';
import { parseTypeDefs, parseTypeExpr, type TypeDef, type TypeNode } from './types/parser.js';

/** Types of non-Id path parameters that 40 does not declare with a `param:` line (DI-12). */
const UNTYPED_PATH_PARAMS: Record<string, string> = {
  flow_type: "OnboardingProgress['flow_type']",
  slug: 'Slug',
  report_type: 'FleetReportType',
  role: 'Role',
  key: 'Str<1,80>',
  dashboard_key: 'DashboardKey',
};

export const CONTRACT_DOC = join(docsDir, '40.API contract.md');
export const GENERATED_DIR = join(backendDir, 'libs', 'contract', 'generated');
export const SCHEMA_ID = 'https://schemas.carpal.app/contract/v1';

export interface GeneratedFile {
  name: string;
  content: string;
}

const json = (v: unknown): string => JSON.stringify(v, null, 2) + '\n';
const HEADER = '// GENERATED by tools/contract/generate.ts from Docs/40.API contract.md. Do not edit.\n';

/** "token, token_type_hint?" (RFC 7009 form fields) → closed object of strings. */
function fieldListSchema(input: string): JsonSchema | null {
  if (!/^[a-z_]+\??(\s*,\s*[a-z_]+\??)*$/.test(input)) return null;
  const names = input.split(',').map((s) => s.trim());
  const properties = Object.fromEntries(names.map((n) => [n.replace('?', ''), { type: 'string', minLength: 1, maxLength: 4096 }]));
  const required = names.filter((n) => !n.endsWith('?'));
  return { type: 'object', properties, ...(required.length ? { required } : {}), additionalProperties: false };
}

function literal(text: string): unknown {
  const t = text.trim();
  if (/^'.*'$/.test(t)) return t.slice(1, -1);
  if (/^-?\d+(\.\d+)?$/.test(t)) return Number(t);
  if (t === 'true' || t === 'false') return t === 'true';
  throw new Error(`Unsupported default value ${text}`);
}

interface OperationSchemas {
  input?: JsonSchema;
  response?: JsonSchema;
  alternateResponses?: Record<string, JsonSchema>;
  query: JsonSchema;
  pathParams: Record<string, JsonSchema>;
}

export function generate(): { files: GeneratedFile[]; summary: string[] } {
  const doc = readFileSync(CONTRACT_DOC, 'utf8');
  const sha = createHash('sha256').update(doc).digest('hex');
  const version = parseContractVersion(doc);
  const all = lines(doc);

  // ----------------------------------------------------------- operations
  const operations = parseOperations(doc);
  const ids = new Set(operations.map((o) => o.opId));
  if (ids.size !== operations.length) throw new Error('Duplicate operation ids in 40');
  const routeKeys = new Map<string, string>();
  for (const o of operations) {
    for (const r of o.routes) {
      const key = `${r.host} ${r.method} ${r.path.replace(/\{[a-z_]+\}/g, '{}')}`;
      const other = routeKeys.get(key);
      if (other) throw new Error(`Route conflict: ${key} (${other}, ${o.opId})`);
      routeKeys.set(key, o.opId);
    }
  }
  const assistAllowlist = parseAssistAllowlist(doc);
  const unknownAssist = assistAllowlist.filter((a) => !ids.has(a));
  if (unknownAssist.length) throw new Error(`Assist allowlist names unknown operations: ${unknownAssist.join(', ')}`);
  const registry: OperationRegistry = {
    source: relative(repoDir, CONTRACT_DOC).replace(/\\/g, '/'),
    sourceSha256: sha,
    contractVersion: version,
    operationCount: operations.length,
    routeCount: operations.reduce((n, o) => n + o.routes.length, 0),
    assistAllowlist,
    operations,
  };

  // ----------------------------------------------------------------- types
  const defs: TypeDef[] = codeBlocks(all)
    .filter((b) => b.lang === 'ts')
    .flatMap((b) => parseTypeDefs(b.body.map((l) => l.text).join('\n'), b.body[0]?.n ?? b.startLine));
  const names = new Set<string>();
  for (const d of defs) {
    if (names.has(d.name)) throw new Error(`Type ${d.name} defined twice (line ${d.line})`);
    names.add(d.name);
  }
  const defBuilder = new SchemaBuilder(defs, '#/$defs/');
  const $defs: Record<string, JsonSchema> = {};
  const defFailures: { type: string; line: number; error: string }[] = [];
  for (const d of [...defs].sort((a, b) => a.name.localeCompare(b.name))) {
    if (d.params.length > 0) continue; // generic templates (Page<T>) are instantiated at use
    try {
      $defs[d.name] = defBuilder.definition(d.name);
    } catch (e) {
      defFailures.push({ type: d.name, line: d.line, error: (e as Error).message });
    }
  }
  const schemas = {
    $schema: 'https://json-schema.org/draft/2020-12/schema',
    $id: SCHEMA_ID,
    'x-custom-keywords': [...CUSTOM_KEYWORDS],
    $defs,
  };

  // ------------------------------------------------------- op schemas
  const opBuilder = new SchemaBuilder(defs, `${SCHEMA_ID}#/$defs/`);
  const opFailures: { opId: string; part: string; type: string; error: string }[] = [];
  const convert = (o: Operation, part: string, type: string): JsonSchema | undefined => {
    try {
      return opBuilder.expression(parseTypeExpr(type));
    } catch (e) {
      opFailures.push({ opId: o.opId, part, type, error: (e as Error).message });
      return undefined;
    }
  };
  const opSchemas: Record<string, OperationSchemas> = {};
  let inputs = 0;
  let inputsOk = 0;
  let responses = 0;
  let responsesOk = 0;
  for (const o of operations) {
    const entry: OperationSchemas = { query: {}, pathParams: {} };
    if (o.inputType) {
      inputs++;
      const s = fieldListSchema(o.inputType) ?? convert(o, 'input', o.inputType);
      if (s) {
        entry.input = s;
        inputsOk++;
      }
    }
    if (o.responseType) {
      responses++;
      const s = convert(o, 'response', o.responseType);
      if (s) {
        entry.response = s;
        responsesOk++;
      }
    }
    for (const alt of o.alternateResponses ?? []) {
      const s = convert(o, `response ${alt.status}`, alt.type);
      if (s) (entry.alternateResponses ??= {})[String(alt.status)] = s;
    }
    // Query: closed object; "cursor?, limit?" shorthand per 40 §3.3 (admin limit up to 100).
    const admin = o.routes.some((r) => r.host === 'admin-api');
    const properties: Record<string, JsonSchema> = {};
    const required: string[] = [];
    // "List operations that show no q: line accept only them" (cursor?, limit?) — 40 §3.3.
    // POST searches carry cursor and limit in their body (TR-7), so only GET lists get them here.
    const query =
      o.query.length === 0 && o.method === 'GET' && /^Page<.+>$/.test(o.responseType ?? '')
        ? [
            { name: 'cursor', type: null, optional: true },
            { name: 'limit', type: null, optional: true },
          ]
        : o.query;
    for (const q of query) {
      let s: JsonSchema | undefined;
      if (q.type === null && q.name === 'cursor') s = convert(o, 'query cursor', 'Cursor');
      else if (q.type === null && q.name === 'limit') s = { type: 'integer', minimum: 1, maximum: admin ? 100 : 50, default: 20 };
      else if (q.type === null)
        opFailures.push({ opId: o.opId, part: `query ${q.name}`, type: '(none)', error: 'query parameter without type' });
      else s = convert(o, `query ${q.name}`, q.type);
      if (!s) continue;
      if (q.default !== undefined) s = { ...s, default: literal(q.default) };
      properties[q.name] = s;
      if (!q.optional) required.push(q.name);
    }
    entry.query = { type: 'object', properties, ...(required.length ? { required } : {}), additionalProperties: false };
    for (const r of o.routes) {
      for (const p of r.pathParams) {
        // Path parameters are Ids unless the block declares `param:`; 40 leaves a few non-Id names
        // untyped (DI-12), typed here from the schemas they name.
        const t = o.pathParamTypes?.[p] ?? UNTYPED_PATH_PARAMS[p];
        entry.pathParams[p] = t ? (convert(o, `path ${p}`, t) ?? {}) : (convert(o, `path ${p}`, 'Id') ?? {});
      }
    }
    opSchemas[o.opId] = entry;
  }

  // ------------------------------------------------------------- catalogs
  const errors = parseErrorCatalog(doc);
  const roleGroups = parseRoleGroups(doc);
  const enumSection = all.findIndex((l) => l.text === '# 5. Enum Registry');
  const enumEnd = all.findIndex((l, i) => i > enumSection && /^# \d+\./.test(l.text));
  const enumDefs = defs.filter((d) => d.line > enumSection && d.line < enumEnd);
  const enums: Record<string, (string | number)[]> = {};
  for (const d of enumDefs) {
    const members: TypeNode[] = d.type.k === 'union' ? d.type.members : [d.type];
    if (members.every((m) => m.k === 'lit' && m.value !== null && typeof m.value !== 'boolean')) {
      enums[d.name] = members.map((m) => (m as { value: string | number }).value);
    }
  }

  const coverage = {
    typeDefinitions: {
      total: defs.filter((d) => d.params.length === 0).length,
      converted: Object.keys($defs).length,
      generic: defs.filter((d) => d.params.length > 0).map((d) => d.name),
      failures: defFailures,
    },
    operationInputs: { total: inputs, converted: inputsOk },
    operationResponses: { total: responses, converted: responsesOk },
    operationFailures: opFailures,
    unresolvedTypeNames: [...new Set([...defBuilder.unresolved, ...opBuilder.unresolved])].sort(),
  };

  const opIdsTs =
    HEADER +
    `\nexport const OPERATION_IDS = [\n${[...ids]
      .sort()
      .map((id) => `  '${id}',`)
      .join('\n')}\n] as const;\n\n` +
    'export type OperationId = (typeof OPERATION_IDS)[number];\n';
  const errorsTs =
    HEADER +
    '\nexport interface ErrorCodeInfo {\n  status: number;\n  meaning: string;\n  /** Implicit on every operation (40 §4.3). */\n  common: boolean;\n}\n\n' +
    `export const ERROR_CODES = {\n${errors.map((e) => `  ${e.code}: { status: ${e.status}, meaning: ${JSON.stringify(e.meaning)}, common: ${e.common} },`).join('\n')}\n} as const satisfies Record<string, ErrorCodeInfo>;\n\n` +
    'export type ErrorCode = keyof typeof ERROR_CODES;\n';
  const enumsTs =
    HEADER +
    `\nexport const ENUMS = {\n${Object.entries(enums)
      .map(([k, v]) => `  ${k}: ${JSON.stringify(v)},`)
      .join('\n')}\n} as const;\n\n` +
    Object.keys(enums)
      .map((k) => `export type ${k} = (typeof ENUMS)['${k}'][number];`)
      .join('\n') +
    '\n';
  const roleGroupsTs =
    HEADER +
    "\nexport interface RoleGroup {\n  readonly roles: readonly string[];\n  /** O+ / M+: only roles of the path organization's type apply. */\n  readonly orgTypeRelative?: boolean;\n  /** ANY: every active member role of the path organization. */\n  readonly anyMember?: boolean;\n}\n\n" +
    `export const ROLE_GROUPS = ${JSON.stringify(roleGroups, null, 2)} as const satisfies Record<string, RoleGroup>;\n\n` +
    'export type RoleGroupName = keyof typeof ROLE_GROUPS;\n';

  const files: GeneratedFile[] = [
    { name: 'operations.json', content: json(registry) },
    { name: 'schemas.json', content: json(schemas) },
    { name: 'operation-schemas.json', content: json({ $comment: `Schemas reference ${SCHEMA_ID}`, operations: opSchemas }) },
    { name: 'schema-coverage.json', content: json(coverage) },
    { name: 'operation-ids.ts', content: opIdsTs },
    { name: 'errors.ts', content: errorsTs },
    { name: 'enums.ts', content: enumsTs },
    { name: 'role-groups.ts', content: roleGroupsTs },
  ];
  const pct = (a: number, b: number): string => `${a}/${b} (${((100 * a) / Math.max(b, 1)).toFixed(1)}%)`;
  const summary = [
    `Contract ${version}, sha256 ${sha.slice(0, 12)}…`,
    `Operations: ${operations.length}, routes: ${registry.routeCount}, assist allowlist: ${assistAllowlist.length}`,
    `Type definitions: ${pct(coverage.typeDefinitions.converted, coverage.typeDefinitions.total)} (+${coverage.typeDefinitions.generic.length} generic)`,
    `Operation inputs: ${pct(inputsOk, inputs)}, responses: ${pct(responsesOk, responses)}`,
    `Errors: ${errors.length}, enums: ${Object.keys(enums).length}, role groups: ${Object.keys(roleGroups).length}`,
    ...(defFailures.length + opFailures.length > 0
      ? [`Unconverted: ${defFailures.length} types, ${opFailures.length} operation parts (see schema-coverage.json)`]
      : []),
  ];
  return { files, summary };
}

function main(): void {
  const check = process.argv.includes('--check');
  const { files, summary } = generate();
  const stale: string[] = [];
  if (!check) mkdirSync(GENERATED_DIR, { recursive: true });
  for (const f of files) {
    const path = join(GENERATED_DIR, f.name);
    const current = existsSync(path) ? readFileSync(path, 'utf8').replace(/\r\n/g, '\n') : null;
    if (current === f.content) continue;
    if (check) stale.push(f.name);
    else writeFileSync(path, f.content);
  }
  for (const line of summary) console.log(line);
  if (check && stale.length > 0) {
    console.error(`Generated contract files are out of date: ${stale.join(', ')}. Run pnpm contract:generate.`);
    process.exit(1);
  }
  console.log(check ? 'Generated contract files are up to date.' : `Wrote ${relative(backendDir, GENERATED_DIR)}`);
}

if (process.argv[1]?.replace(/\\/g, '/').endsWith('tools/contract/generate.ts')) main();
